import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: string;
  scale: number;
  compact: boolean;
  fontFamily: string;
}

const THEMES = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces' },
  { value: 'mono', label: 'JetBrains Mono' },
];

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: defaultValue?.theme ?? 'system',
    scale: defaultValue?.scale ?? 100,
    compact: defaultValue?.compact ?? false,
    fontFamily: defaultValue?.fontFamily ?? 'sans',
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    THEMES.find((item) => item.value === settings.theme)?.label ?? settings.theme;

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 560,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: 20,
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: 14 }}>Тема</span>
        <JxToggle
          aria-label="Тема оформления"
          items={THEMES}
          value={settings.theme}
          onValueChange={(theme) => update({ theme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.compact}
        onChange={(event) => update({ compact: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={FONTS}
        value={settings.fontFamily}
        onValueChange={(fontFamily) => update({ fontFamily })}
      />
    </section>
  );
}

